using GraphApi.Models.NTF.TiposNotificacion;namespace GraphApi.Services.NTF.TiposNotificacion{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposNotificacions.    /// </summary>    public interface ITiposNotificacionService    {        /// <summary>        /// Obtiene la lista de TiposNotificacions con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposNotificacion>> GetTiposNotificacions(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposNotificacions con filtros opcionales.        /// </summary>        /// <param name="tipoNotificacionID">Filtro opcional para TipoNotificacionID.</param>        /// <param name="tipoNotiicfacion">Filtro opcional para TipoNotiicfacion.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposNotificacionsDynamic(            int? tipoNotificacionID,            string? tipoNotiicfacion,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposNotificacion.        /// </summary>        /// <param name="objInput">Datos para crear el TiposNotificacion.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposNotificacion> CreateTiposNotificacion(            clCreateTiposNotificacion objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposNotificacion.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposNotificacion, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposNotificacion?> UpdateTiposNotificacion(            clUpdateTiposNotificacion objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposNotificacion por su ID.        /// </summary>        /// <param name="nTiposNotificacionID">ID del TiposNotificacion a eliminar.</param>        Task<bool> DeleteTiposNotificacion(int nTiposNotificacionID);    }}